Solution A: ```javascript
function generateAndSolveMaze(canvasId) {
    const canvas = document.getElementById(canvasId);
    if (!canvas || !(canvas instanceof HTMLCanvasElement)) {
        console.error('Canvas element not found or invalid');
        return;
    }
    const ctx = canvas.getContext('2d');
    const size = 50;  // grid dimension
    const cellSize = canvas.width / size;
    const DELAY = 20; // ms between steps

    // State codes
    const ST = {
        EMPTY: 0,
        WALL: 1,
        OPENSET: 2,
        CLOSEDSET: 3,
        CURRENT: 4,
        SOLUTION: 5
    };

    // Grid initialized to EMPTY
    const grid = Array.from({ length: size }, () => Array(size).fill(ST.EMPTY));

    // Helper to async delay
    function pause() { return new Promise(r => setTimeout(r, DELAY)); }

    // Draw entire grid
    function drawGrid() {
        for (let y = 0; y < size; y++) {
            for (let x = 0; x < size; x++) {
                switch (grid[y][x]) {
                    case ST.WALL: ctx.fillStyle = '#000'; break;
                    case ST.OPENSET: ctx.fillStyle = '#add8e6'; break;
                    case ST.CLOSEDSET: ctx.fillStyle = '#d3d3d3'; break;
                    case ST.CURRENT: ctx.fillStyle = '#ff8c00'; break;
                    case ST.SOLUTION: ctx.fillStyle = '#32cd32'; break;
                    default: ctx.fillStyle = '#fff'; break;
                }
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            }
        }
    }

    // Random integer inclusive
    function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }

    // Recursive division algorithm
    async function divide(x1, y1, x2, y2) {
        const width = x2 - x1 + 1;
        const height = y2 - y1 + 1;
        if (width < 2 || height < 2) return;

        const horizontal = width < height;
        if (horizontal) {
            const wallY = randInt(y1 + 1, y2 - 1);
            const passageX = randInt(x1, x2);
            for (let x = x1; x <= x2; x++) {
                if (x === passageX) {
                    grid[wallY][x] = ST.EMPTY;
                } else {
                    grid[wallY][x] = ST.WALL;
                    await pause();
                    drawGrid();
                }
            }
            await divide(x1, y1, x2, wallY - 1);
            await divide(x1, wallY + 1, x2, y2);
        } else {
            const wallX = randInt(x1 + 1, x2 - 1);
            const passageY = randInt(y1, y2);
            for (let y = y1; y <= y2; y++) {
                if (y === passageY) {
                    grid[y][wallX] = ST.EMPTY;
                } else {
                    grid[y][wallX] = ST.WALL;
                    await pause();
                    drawGrid();
                }
            }
            await divide(x1, y1, wallX - 1, y2);
            await divide(wallX + 1, y1, x2, y2);
        }
    }

    // A* search
    async function solve() {
        const start = {x:0, y:0};
        const goal = {x:size-1, y:size-1};
        grid[start.y][start.x] = ST.EMPTY;
        grid[goal.y][goal.x] = ST.EMPTY;
        drawGrid();

        const openSet = [];
        const cameFrom = Array.from({ length: size }, () => Array(size).fill(null));
        const gScore = Array.from({ length: size }, () => Array(size).fill(Infinity));
        const fScore = Array.from({ length: size }, () => Array(size).fill(Infinity));

        function heuristic(a,b){ return Math.abs(a.x-b.x)+Math.abs(a.y-b.y); }

        openSet.push(start);
        gScore[start.y][start.x] = 0;
        fScore[start.y][start.x] = heuristic(start,goal);

        while (openSet.length) {
            // Sort openSet by fScore
            openSet.sort((a,b)=>fScore[a.y][a.x]-fScore[b.y][b.x]);
            const current = openSet.shift();
            if (grid[current.y][current.x] !== ST.EMPTY) grid[current.y][current.x] = ST.CURRENT;
            drawGrid();
            await pause();

            if (current.x===goal.x && current.y===goal.y) {
                // reconstruct path
                let cur = current;
                while (cur) {
                    grid[cur.y][cur.x] = ST.SOLUTION;
                    cur = cameFrom[cur.y][cur.x];
                    await pause();
                    drawGrid();
                }
                return;
            }

            const neighbors = [
                {x:current.x+1, y:current.y},
                {x:current.x-1, y:current.y},
                {x:current.x, y:current.y+1},
                {x:current.x, y:current.y-1}
            ];

            for (const n of neighbors) {
                if (n.x<0||n.x>=size||n.y<0||n.y>=size) continue;
                if (grid[n.y][n.x]===ST.WALL) continue;
                const tentativeG = gScore[current.y][current.x] + 1;
                if (tentativeG < gScore[n.y][n.x]) {
                    cameFrom[n.y][n.x] = current;
                    gScore[n.y][n.x] = tentativeG;
                    fScore[n.y][n.x] = tentativeG + heuristic(n,goal);
                    if (!openSet.find(c=>c.x===n.x&&c.y===n.y)) {
                        openSet.push(n);
                        if (grid[n.y][n.x]!==ST.SOLUTION) grid[n.y][n.x]=ST.OPENSET;
                    }
                }
            }
            if (grid[current.y][current.x]!==ST.SOLUTION) grid[current.y][current.x]=ST.CLOSEDSET;
            drawGrid();
            await pause();
        }
    }

    // Main execution
    (async function main() {
        await divide(0,0,size-1,size-1);
        await pause();
        await solve();
    })();
}
```

Solution B: function generateMaze(canvasID) {
    const canvas = document.getElementById(canvasID);
    const ctx = canvas.getContext('2d');
    const width = 500, height = 500;
    canvas.width = width;
    canvas.height = height;

    // Recursively divide cells to generate maze
    function divide(x, y, w, h) {
        if (w < 5 || h < 5) return;
        let nx = x + w, ny = y + h;
        if (Math.random() < 0.5) {
            if (w > h) {
                let dx = x + Math.floor(w / 2);
                ctx.moveTo(dx, y); ctx.lineTo(dx, ny); // Vertical line
                if (divide(x, y, w / 2, h) || divide(dx + 1, y, w - 2, h)) return true;
            } else {
                let dy = y + Math.floor(h / 2);
                ctx.moveTo(x, dy); ctx.lineTo(nx, dy); // Horizontal line
                if (divide(x, y, w, h / 2) || divide(x, dy + 1, w, h - 2)) return true;
            }
        }
        return false;
    }

    ctx.beginPath(); ctx.rect(0, 0, width, height); ctx.stroke();
    divide(1, 1, width - 2, height - 2);

    // A* search function to solve maze
    function astar(start, end) {
        let openSet = [start], cameFrom = {}, costSoFar = {}, heuristic = (a, b) => ((a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2) ** 0.5;
        costSoFar[start] = 0;
        while (openSet.length) {
            let current = openSet.pop();
            if (current[0] === end[0] && current[1] === end[1]) break;
            let neighbors = [[0, -1], [0, 1], [-1, 0], [1, 0]];
            for (let [dx, dy] of neighbors) {
                let next = [current[0] + dx, current[1] + dy];
                let nextCost = costSoFar[current] + 1;
                if (next[0] < 0 || next[0] >= width || next[1] < 0 || next[1] >= height || cell[next[0]][next[1]] !== 0) continue;
                if (costSoFar[next] === undefined || nextCost < costSoFar[next]) {
                    cameFrom[next] = current;
                    costSoFar[next] = nextCost;
                    openSet.push(next);
                }
            }
            ctx.fillStyle = '# Farbe für aktuellen Pfad';
            ctx.fillText(' ', [current[0] * 10, current[1] * 10]);
        }
        let totalPath = trace(cameFrom, start, end);
        ctx.fillStyle = '# Farbe für Lösung';
        for (let cell of totalPath) ctx.fillText(' ', [cell[0] * 10, cell[1] * 10]);
    }

    // Trace path backward from cameFrom map
    function trace(cameFrom, start, end) {
        let path = [end];
        while (path[0] !== start) { let p = cameFrom[path[0]]; path.unshift(p); }
        return path;
    }

    // Cell representation for A*
    let cell = Array.from({ length: width }, () => new Array(height).fill(0));
    for (let x = 0; x < width; x++) {
        for (let y = 0; y < height; y++) {
            if (!(x % 10) || !(y % 10)) cell[x][y] |= 2; // Walls
            if (x > 0 && x < width - 1 && y > 0 && y < height - 1 && cell[x][y] === 0) { // Path nodes
                let oneWay = Math.random() < 0.5 ? [[0, -1], [0, 1]] : [[-1, 0], [1, 0]];
                for (let [dx, dy] of oneWay) {
                    let nx = x + dx, ny = y + dy;
                    if (cell[nx][ny] === 2) {
                        cell[x][y] |= 1;
                        break;
                    }
                }
            }
        }
    }
    // Start and end points
    let start = [1, 1], end = [width - 2, height - 2];
    cell[start[0]][start[1]] = 3; // Start point
    cell[end[0]][end[1]] = 4; // End point

    // Draw cells
    for (let x = 0; x < width; x++) { for (let y = 0; y < height; y++) { ctx.fillStyle = '# Farbe für Celltyp ' + cell[x][y]; ctx.fillText(' ', [x * 10, y * 10]); } }
    astar(start, end); // Solve
}

